head.b:skin:
/* =========================================================
   Pocket FM Story Info Blogger Template
   Edit global visual tokens below for branding.
   ========================================================= */
:root {
  color-scheme: light;
  --bg: #f7f8fb;
  --surface: #ffffff;
  --surface-2: #f1f5f9;
  --text: #101827;
  --muted: #667085;
  --border: #e5e7eb;
  --brand: #ef3f5a;
  --brand-2: #7c3aed;
  --brand-dark: #be123c;
  --success: #059669;
  --warning: #d97706;
  --shadow: 0 18px 45px rgba(15, 23, 42, .10);
  --radius: 22px;
  --nav-height: 72px;
  --container: 1180px;
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --bg: #070b14;
    --surface: #101827;
    --surface-2: #172033;
    --text: #eef2ff;
    --muted: #a6b0c3;
    --border: #263247;
    --shadow: 0 18px 45px rgba(0, 0, 0, .35);
  }
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(circle at top left, rgba(239, 63, 90, .12), transparent 32rem), var(--bg);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.55;
  text-rendering: optimizeLegibility;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button, input, select { font: inherit; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.skip-link {
  position: fixed; left: 1rem; top: -8rem; z-index: 10000;
  background: var(--text); color: var(--surface); padding: .8rem 1rem; border-radius: 999px;
}
.skip-link:focus { top: 1rem; }
.site-nav {
  position: fixed; inset: 0 0 auto 0; z-index: 9999; height: var(--nav-height);
  background: rgba(255, 255, 255, .84); backdrop-filter: saturate(160%) blur(18px);
  border-bottom: 1px solid rgba(229, 231, 235, .72);
}
@media (prefers-color-scheme: dark) { .site-nav { background: rgba(16, 24, 39, .82); border-color: rgba(38, 50, 71, .72); } }
.nav-inner { width: min(100% - 32px, var(--container)); height: 100%; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.logo { display: inline-flex; align-items: center; gap: .7rem; font-weight: 900; letter-spacing: -.03em; font-size: clamp(1.05rem, 2vw, 1.35rem); }
.logo-mark { width: 42px; aspect-ratio: 1; border-radius: 14px; display: grid; place-items: center; color: white; background: linear-gradient(135deg, var(--brand), var(--brand-2)); box-shadow: 0 10px 28px rgba(239, 63, 90, .35); }
.nav-links { display: flex; align-items: center; gap: .25rem; list-style: none; margin: 0; padding: 0; }
.nav-links a { display: inline-flex; padding: .62rem .85rem; border-radius: 999px; color: var(--muted); font-weight: 700; font-size: .94rem; transition: color .2s ease, background .2s ease, transform .2s ease; }
.nav-links a:hover, .nav-links a:focus-visible { color: var(--text); background: var(--surface-2); transform: translateY(-1px); }
.nav-toggle { display: none; border: 0; border-radius: 14px; background: var(--surface-2); color: var(--text); padding: .7rem .85rem; cursor: pointer; }
main { padding-top: var(--nav-height); }
.container { width: min(100% - 32px, var(--container)); margin: 0 auto; }
.hero { padding: clamp(2.5rem, 7vw, 5rem) 0 2rem; }
.hero-card { background: linear-gradient(135deg, rgba(239, 63, 90, .96), rgba(124, 58, 237, .92)); color: white; border-radius: calc(var(--radius) + 10px); padding: clamp(1.5rem, 5vw, 3.5rem); box-shadow: var(--shadow); overflow: hidden; position: relative; }
.hero-card:after { content: ""; position: absolute; width: 18rem; aspect-ratio: 1; border-radius: 50%; right: -5rem; top: -5rem; background: rgba(255,255,255,.18); }
.hero h1 { margin: 0 0 .9rem; max-width: 760px; font-size: clamp(2rem, 6vw, 4.7rem); line-height: .98; letter-spacing: -.06em; }
.hero p { margin: 0; max-width: 760px; color: rgba(255,255,255,.88); font-size: clamp(1rem, 2.4vw, 1.25rem); }
.notice { margin-top: 1rem; display: inline-flex; align-items: center; gap: .5rem; padding: .6rem .85rem; border-radius: 999px; background: rgba(255,255,255,.16); color: white; font-weight: 800; font-size: .9rem; }
.controls { position: sticky; top: var(--nav-height); z-index: 30; padding: 1rem 0; background: linear-gradient(to bottom, var(--bg) 78%, transparent); }
.search-row { display: grid; grid-template-columns: 1fr auto; gap: .8rem; align-items: center; }
.search-box { position: relative; }
.search-box input { width: 100%; border: 1px solid var(--border); border-radius: 18px; padding: 1rem 1rem 1rem 3rem; background: var(--surface); color: var(--text); box-shadow: 0 8px 24px rgba(15,23,42,.05); outline: none; }
.search-box svg { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); color: var(--muted); }
.control-btn { border: 0; border-radius: 16px; padding: 1rem 1.1rem; color: white; background: linear-gradient(135deg, var(--brand), var(--brand-2)); font-weight: 900; cursor: pointer; box-shadow: 0 12px 26px rgba(124,58,237,.22); }
.filter-panel { display: grid; grid-template-columns: repeat(5, minmax(130px, 1fr)); gap: .75rem; margin-top: .85rem; }
.filter-panel select { width: 100%; border: 1px solid var(--border); border-radius: 14px; padding: .82rem .75rem; background: var(--surface); color: var(--text); outline: none; }
.result-meta { display: flex; justify-content: space-between; gap: 1rem; color: var(--muted); font-weight: 700; padding: .65rem 0 1rem; }
.story-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(155px, 1fr)); gap: clamp(.9rem, 2vw, 1.25rem); padding-bottom: 2rem; }
.story-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; box-shadow: 0 9px 24px rgba(15,23,42,.06); transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease; content-visibility: auto; contain-intrinsic-size: 250px 320px; }
.story-card:hover { transform: translateY(-5px); border-color: rgba(239,63,90,.32); box-shadow: var(--shadow); }
.poster-wrap { aspect-ratio: 1 / 1; background: var(--surface-2); overflow: hidden; }
.poster-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
.story-card:hover img { transform: scale(1.04); }
.card-title { min-height: 64px; display: grid; align-items: center; padding: .85rem; font-weight: 900; line-height: 1.25; letter-spacing: -.02em; }
.card-subtitle { display: block; margin-top: .25rem; color: var(--muted); font-size: .78rem; font-weight: 700; }
.load-row { display: flex; justify-content: center; padding: 1rem 0 3rem; }
.empty-state { padding: 2rem; text-align: center; border: 1px dashed var(--border); border-radius: var(--radius); background: var(--surface); color: var(--muted); }
.detail-layout { display: grid; grid-template-columns: minmax(240px, 390px) 1fr; gap: clamp(1.2rem, 4vw, 3rem); align-items: start; padding: clamp(2rem, 5vw, 4rem) 0; }
.detail-poster { border-radius: calc(var(--radius) + 4px); overflow: hidden; background: var(--surface-2); box-shadow: var(--shadow); position: sticky; top: calc(var(--nav-height) + 1.5rem); }
.detail-poster img { width: 100%; aspect-ratio: 1 / 1; object-fit: cover; }
.detail-card { background: var(--surface); border: 1px solid var(--border); border-radius: calc(var(--radius) + 4px); padding: clamp(1.2rem, 3vw, 2rem); box-shadow: 0 12px 32px rgba(15,23,42,.06); }
.breadcrumbs { display: flex; flex-wrap: wrap; gap: .4rem; color: var(--muted); font-size: .9rem; font-weight: 700; margin-bottom: 1rem; }
.detail-title { margin: 0 0 .8rem; font-size: clamp(2rem, 5vw, 4rem); line-height: 1; letter-spacing: -.06em; }
.badges { display: flex; flex-wrap: wrap; gap: .55rem; margin: 1rem 0 1.2rem; }
.badge { display: inline-flex; align-items: center; border: 1px solid var(--border); background: var(--surface-2); color: var(--muted); border-radius: 999px; padding: .42rem .7rem; font-weight: 800; font-size: .82rem; }
.info-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; margin: 1.2rem 0; }
.info-item { border: 1px solid var(--border); border-radius: 16px; padding: .85rem; background: var(--surface-2); }
.info-label { display: block; color: var(--muted); font-size: .78rem; font-weight: 900; text-transform: uppercase; letter-spacing: .08em; }
.info-value { display: block; margin-top: .2rem; font-weight: 900; }
.description { color: var(--muted); font-size: 1.03rem; }
.static-page { padding: clamp(2rem, 6vw, 4rem) 0; }
.page-content { color: var(--muted); font-size: 1.03rem; }
.page-content a { color: var(--brand); font-weight: 800; }
.pocket-btn { display: inline-flex; align-items: center; justify-content: center; gap: .6rem; width: min(100%, 360px); margin-top: 1.2rem; border-radius: 18px; padding: 1rem 1.25rem; color: white; background: linear-gradient(135deg, var(--brand), var(--brand-dark)); font-weight: 1000; box-shadow: 0 14px 32px rgba(239,63,90,.28); }
.related-section { padding: 0 0 4rem; }
.section-title { margin: 0 0 1rem; font-size: clamp(1.4rem, 3vw, 2rem); letter-spacing: -.04em; }
.related-row { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(145px, 180px); gap: 1rem; overflow-x: auto; padding: .25rem .15rem 1rem; scroll-snap-type: x mandatory; }
.related-row .story-card { scroll-snap-align: start; }
[hidden] { display: none !important; }
.directory-panel { margin-top: 1rem; display: flex; flex-wrap: wrap; gap: .6rem; }
.directory-chip { border: 1px solid var(--border); background: var(--surface); color: var(--text); border-radius: 999px; padding: .55rem .8rem; font-weight: 900; cursor: pointer; box-shadow: 0 8px 20px rgba(15,23,42,.06); }
.directory-chip:hover, .directory-chip:focus-visible { border-color: rgba(239,63,90,.55); transform: translateY(-1px); }
.blog-posts, .post-footer, .comments, .feed-links, .blog-pager, .status-msg-wrap { display: none !important; }
.footer { border-top: 1px solid var(--border); background: var(--surface); padding: 2rem 0; color: var(--muted); }
.footer-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1rem; }
@media (max-width: 860px) {
  .nav-toggle { display: inline-flex; }
  .nav-links { position: fixed; top: var(--nav-height); left: 16px; right: 16px; display: grid; gap: .2rem; padding: .8rem; border: 1px solid var(--border); border-radius: 20px; background: var(--surface); box-shadow: var(--shadow); transform-origin: top; transform: scaleY(0); opacity: 0; pointer-events: none; transition: transform .18s ease, opacity .18s ease; }
  .site-nav.is-open .nav-links { transform: scaleY(1); opacity: 1; pointer-events: auto; }
  .nav-links a { padding: .8rem 1rem; }
  .filter-panel { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .detail-layout { grid-template-columns: 1fr; }
  .detail-poster { position: static; max-width: 420px; width: 100%; margin: 0 auto; }
}
@media (max-width: 560px) {
  :root { --nav-height: 66px; }
  .nav-inner, .container { width: min(100% - 22px, var(--container)); }
  .search-row { grid-template-columns: 1fr; }
  .filter-panel { grid-template-columns: 1fr; }
  .story-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; }
  .card-title { min-height: 58px; font-size: .92rem; padding: .7rem; }
  .info-grid { grid-template-columns: 1fr; }
}

body.script:
/* =========================================================
   Pocket FM Story Database JavaScript
   Admin global controls are intentionally grouped first.
   ========================================================= */
const POCKETFM_CONFIG = {
  SHOW_POCKETFM_BUTTON: true,
  FEED_BATCH_SIZE: 150,
  INITIAL_VISIBLE_COUNT: 24,
  VISIBLE_INCREMENT: 24,
  PLACEHOLDER_POSTER: 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 720"%3E%3Cdefs%3E%3ClinearGradient id="g" x1="0" x2="1" y1="0" y2="1"%3E%3Cstop stop-color="%23ef3f5a"/%3E%3Cstop offset="1" stop-color="%237c3aed"/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width="720" height="720" rx="48" fill="url(%23g)"/%3E%3Ctext x="50%25" y="52%25" text-anchor="middle" font-family="Arial" font-size="84" fill="white"%3EStory%3C/text%3E%3C/svg%3E'
};

const appState = {
  stories: [],
  filtered: [],
  loadedAll: false,
  nextIndex: 1,
  visibleCount: POCKETFM_CONFIG.INITIAL_VISIBLE_COUNT,
  filters: { genre: '', subGenre: '', voiceArtist: '', status: '', language: '' },
  query: ''
};

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));
const normalize = value => String(value || '').trim();
const slugify = value => normalize(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const escapeHtml = value => normalize(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

function getBlogBaseUrl() {
  const canonical = document.querySelector('link[rel="canonical"]');
  if (canonical && canonical.href) {
    const url = new URL(canonical.href);
    const pathParts = url.pathname.split('/');
    if (pathParts.includes('p') || pathParts.includes('search')) return `${url.origin}/`;
  }
  return `${location.origin}/`;
}

function decodeHtml(html) {
  const doc = new DOMParser().parseFromString(String(html || ''), 'text/html');
  return doc.documentElement.textContent || '';
}

function cleanJsonText(value) {
  return decodeHtml(value)
    .replace(/\u00a0/g, ' ')
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/,\s*([}\]])/g, '$1')
    .trim();
}

function extractJsonFromText(value) {
  const text = cleanJsonText(value);
  const storyDataMatch = text.match(/STORY_DATA_START([\s\S]*?)STORY_DATA_END/i);
  if (storyDataMatch) return storyDataMatch[1].trim();
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) return text.slice(firstBrace, lastBrace + 1).trim();
  return '';
}

function parseJsonCandidate(raw, fallbackTitle) {
  const candidate = extractJsonFromText(raw);
  if (!candidate) return null;
  try {
    return JSON.parse(candidate);
  } catch (error) {
    console.warn('Invalid story metadata JSON for', fallbackTitle, error, candidate);
    return null;
  }
}

function parseStoryMetadata(html, fallbackTitle, fallbackUrl) {
  const doc = new DOMParser().parseFromString(String(html || ''), 'text/html');
  const candidates = [];
  doc.querySelectorAll('#story-data, script[type="application/json"][data-story], template[data-story-json], [data-story-json], .story-json, textarea.story-json, pre.story-json').forEach(node => {
    candidates.push(node.textContent || node.innerHTML || '');
  });
  candidates.push(doc.body?.textContent || '');
  candidates.push(String(html || ''));
  let data = {};
  for (const candidate of candidates) {
    const parsed = parseJsonCandidate(candidate, fallbackTitle);
    if (parsed && typeof parsed === 'object') {
      data = parsed;
      break;
    }
  }
  const firstImage = doc.querySelector('img');
  const plainBodyText = (doc.body?.textContent || '').replace(/STORY_DATA_START[\s\S]*?STORY_DATA_END/i, '').trim();
  const description = data.description || doc.querySelector('[data-description]')?.textContent || plainBodyText.slice(0, 220);
  return {
    title: normalize(data.storyName || data.name || fallbackTitle),
    poster: normalize(data.posterUrl || data.posterURL || data.poster || firstImage?.getAttribute('src') || POCKETFM_CONFIG.PLACEHOLDER_POSTER),
    pocketUrl: normalize(data.pocketFmUrl || data.pocketFMUrl || data.pocketUrl || data.officialUrl || '#'),
    genre: normalize(data.genre),
    subGenre: normalize(data.subGenre || data.subgenre),
    language: normalize(data.language),
    voiceArtist: normalize(data.voiceArtist || data.narrator),
    status: normalize(data.status),
    episodes: normalize(data.episodes),
    author: normalize(data.author),
    description: normalize(description),
    releaseYear: normalize(data.releaseYear),
    listeningHours: normalize(data.totalListeningHours || data.listeningHours),
    rating: normalize(data.rating),
    tags: Array.isArray(data.tags) ? data.tags.map(normalize).filter(Boolean) : normalize(data.tags).split(',').map(normalize).filter(Boolean),
    url: fallbackUrl,
    slug: slugify(fallbackTitle)
  };
}

function getFeedEntryAlternateUrl(entry) {
  return (entry.link || []).find(item => item.rel === 'alternate')?.href || '#';
}

function storyFromFeedEntry(entry) {
  const title = decodeHtml(entry.title?.$t || 'Untitled Story');
  const link = getFeedEntryAlternateUrl(entry);
  const content = entry.content?.$t || entry.summary?.$t || '';
  return parseStoryMetadata(content, title, link);
}

function comparableUrl(value) {
  try {
    const url = new URL(value, location.origin);
    return `${url.origin}${url.pathname.replace(/\/$/, '')}`;
  } catch (error) {
    return normalize(value).replace(/\/$/, '');
  }
}

function isCurrentPostStory(story) {
  const canonical = document.querySelector('link[rel="canonical"]')?.href || location.href;
  return comparableUrl(story.url) === comparableUrl(canonical) || comparableUrl(story.url) === comparableUrl(location.href);
}

async function fetchFeedEntries(feedUrl) {
  const response = await fetch(feedUrl, { credentials: 'same-origin' });
  if (!response.ok) throw new Error(`Feed request failed: ${response.status}`);
  const payload = await response.json();
  return payload.feed?.entry || [];
}


function getCurrentPostMetadataFromDom() {
  const canonical = document.querySelector('link[rel="canonical"]')?.href || location.href;
  const currentArticle = $$('.blog-posts .post').find(post => {
    const href = $('h2 a', post)?.href;
    return href && comparableUrl(href) === comparableUrl(canonical);
  }) || $('.blog-posts .post');
  if (!currentArticle) return null;
  const title = $('h2 a', currentArticle)?.textContent || $('.detail-title')?.textContent || document.title;
  const body = $('.post-body', currentArticle)?.innerHTML || currentArticle.innerHTML || '';
  return parseStoryMetadata(body, title, canonical);
}

async function getCurrentPostMetadata() {
  const fallbackTitle = $('.detail-title')?.textContent || document.title;
  const canonical = document.querySelector('link[rel="canonical"]')?.href || location.href;
  const currentPath = new URL(canonical, location.origin).pathname;
  const directFeedUrl = `${getBlogBaseUrl()}feeds/posts/default?alt=json&path=${encodeURI(currentPath)}`;
  const domStory = getCurrentPostMetadataFromDom();
  if (domStory && (domStory.title || domStory.description || domStory.pocketUrl !== '#')) return domStory;

  try {
    const directEntries = await fetchFeedEntries(directFeedUrl);
    const directStories = directEntries.map(storyFromFeedEntry);
    const directMatch = directStories.find(isCurrentPostStory) || directStories[0];
    if (directMatch) return directMatch;
  } catch (error) {
    console.warn('Direct current-post feed lookup failed; trying batched feed fallback.', error);
  }

  while (!appState.loadedAll) {
    await fetchStoriesBatch();
    const currentMatch = appState.stories.find(isCurrentPostStory);
    if (currentMatch) return currentMatch;
  }

  const titleMatch = appState.stories.find(story => story.title === fallbackTitle);
  if (titleMatch) return titleMatch;

  throw new Error(`Current story metadata was not found in the Blogger feed for ${canonical}`);
}

async function fetchStoriesBatch() {
  if (appState.loadedAll) return [];
  const feedUrl = `${getBlogBaseUrl()}feeds/posts/default?alt=json&max-results=${POCKETFM_CONFIG.FEED_BATCH_SIZE}&start-index=${appState.nextIndex}`;
  const response = await fetch(feedUrl, { credentials: 'same-origin' });
  if (!response.ok) throw new Error(`Feed request failed: ${response.status}`);
  const payload = await response.json();
  const entries = payload.feed?.entry || [];
  const stories = entries.map(storyFromFeedEntry);
  appState.nextIndex += entries.length;
  if (entries.length < POCKETFM_CONFIG.FEED_BATCH_SIZE) appState.loadedAll = true;
  appState.stories.push(...stories);
  return stories;
}

function cardTemplate(story) {
  return `<a class="story-card" href="${escapeHtml(story.url)}" data-genre="${escapeHtml(story.genre)}" data-voice="${escapeHtml(story.voiceArtist)}">
    <span class="poster-wrap"><img alt="${escapeHtml(story.title)} poster" decoding="async" height="400" loading="lazy" src="${escapeHtml(story.poster)}" width="400"></span>
    <span class="card-title">${escapeHtml(story.title)}<small class="card-subtitle">${escapeHtml(story.voiceArtist || story.genre || 'Story details')}</small></span>
  </a>`;
}

function applyFilters() {
  const query = appState.query.toLowerCase();
  appState.filtered = appState.stories.filter(story => {
    const searchText = `${story.title} ${story.voiceArtist} ${story.genre}`.toLowerCase();
    const matchesQuery = !query || searchText.includes(query);
    const matchesFilters = Object.entries(appState.filters).every(([key, value]) => !value || story[key] === value);
    return matchesQuery && matchesFilters;
  });
}

function renderFilterOptions() {
  const filterPanel = $('#filterPanel');
  if (!filterPanel) return;
  ['genre', 'subGenre', 'voiceArtist', 'status', 'language'].forEach(key => {
    const select = filterPanel.querySelector(`[data-filter="${key}"]`);
    if (!select) return;
    const current = select.value;
    const label = select.options[0].textContent;
    const values = [...new Set(appState.stories.map(story => story[key]).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    select.innerHTML = `<option value="">${escapeHtml(label)}</option>` + values.map(value => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');
    select.value = values.includes(current) ? current : '';
  });
}

function hydrateFilterFromUrl() {
  const params = new URLSearchParams(location.search);
  const keys = ['genre', 'subGenre', 'voiceArtist', 'status', 'language'];
  keys.forEach(key => {
    const value = params.get(key);
    if (value && appState.stories.some(story => story[key] === value)) appState.filters[key] = value;
  });
  const labelMatch = location.pathname.match(/\/search\/label\/([^/?#]+)/);
  if (labelMatch) {
    const labelValue = decodeURIComponent(labelMatch[1].replace(/\+/g, ' '));
    const matchingKey = keys.find(key => appState.stories.some(story => story[key] === labelValue));
    if (matchingKey && !appState.filters[matchingKey]) appState.filters[matchingKey] = labelValue;
  }
  keys.forEach(key => {
    const select = document.querySelector(`[data-filter="${key}"]`);
    if (select) select.value = appState.filters[key] || '';
  });
}

function renderDirectoryPanel() {
  const panel = $('#directoryPanel');
  if (!panel) return;
  const params = new URLSearchParams(location.search);
  const directory = params.get('directory');
  const config = directory === 'genres'
    ? { key: 'genre', title: 'Browse Genres' }
    : directory === 'voice-artists'
      ? { key: 'voiceArtist', title: 'Browse Voice Artists' }
      : null;
  if (!config) {
    panel.hidden = true;
    panel.innerHTML = '';
    return;
  }
  const values = [...new Set(appState.stories.map(story => story[config.key]).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  panel.hidden = false;
  panel.innerHTML = `<strong class="section-title" style="width:100%;font-size:1.15rem">${config.title}</strong>` + values.map(value => `<button class="directory-chip" type="button" data-directory-key="${config.key}" data-directory-value="${escapeHtml(value)}">${escapeHtml(value)}</button>`).join('');
  $$('.directory-chip', panel).forEach(button => button.addEventListener('click', () => {
    appState.filters[button.dataset.directoryKey] = button.dataset.directoryValue;
    const select = document.querySelector(`[data-filter="${button.dataset.directoryKey}"]`);
    if (select) select.value = button.dataset.directoryValue;
    appState.visibleCount = POCKETFM_CONFIG.INITIAL_VISIBLE_COUNT;
    renderGrid();
    $('#storyGrid')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }));
}

function renderGrid() {
  const grid = $('#storyGrid');
  const resultCount = $('#resultCount');
  const activeFilterText = $('#activeFilterText');
  const loadMore = $('#loadMore');
  if (!grid) return;
  applyFilters();
  const visible = appState.filtered.slice(0, appState.visibleCount);
  grid.innerHTML = visible.length ? visible.map(cardTemplate).join('') : '<div class="empty-state">No stories match your current search or filters.</div>';
  if (resultCount) resultCount.textContent = `${appState.filtered.length} matching stories`;
  const active = Object.entries(appState.filters).filter(([, value]) => value).map(([key, value]) => `${key}: ${value}`);
  if (activeFilterText) activeFilterText.textContent = active.length ? active.join(' · ') : 'All stories';
  if (loadMore) loadMore.style.display = (!appState.loadedAll || appState.visibleCount < appState.filtered.length) ? 'inline-flex' : 'none';
}

async function loadMoreStories() {
  const before = appState.stories.length;
  if (appState.visibleCount < appState.filtered.length) {
    appState.visibleCount += POCKETFM_CONFIG.VISIBLE_INCREMENT;
    renderGrid();
    return;
  }
  if (!appState.loadedAll) {
    $('#loadMore')?.setAttribute('disabled', 'disabled');
    await fetchStoriesBatch();
    renderFilterOptions();
    appState.visibleCount += POCKETFM_CONFIG.VISIBLE_INCREMENT;
    renderGrid();
    $('#loadMore')?.removeAttribute('disabled');
  }
  if (appState.stories.length === before && appState.loadedAll) renderGrid();
}

function initIndexPage() {
  if (!$('#storyGrid')) return;
  $('#storySearch')?.addEventListener('input', event => { appState.query = event.target.value; appState.visibleCount = POCKETFM_CONFIG.INITIAL_VISIBLE_COUNT; renderGrid(); });
  $$('#filterPanel select').forEach(select => select.addEventListener('change', event => { appState.filters[event.target.dataset.filter] = event.target.value; appState.visibleCount = POCKETFM_CONFIG.INITIAL_VISIBLE_COUNT; renderGrid(); }));
  $('#clearFilters')?.addEventListener('click', () => {
    appState.filters = { genre: '', subGenre: '', voiceArtist: '', status: '', language: '' };
    appState.query = '';
    $('#storySearch').value = '';
    $$('#filterPanel select').forEach(select => { select.value = ''; });
    renderGrid();
  });
  $('#loadMore')?.addEventListener('click', loadMoreStories);
  fetchStoriesBatch().then(() => { renderFilterOptions(); hydrateFilterFromUrl(); renderDirectoryPanel(); renderGrid(); }).catch(error => {
    console.error(error);
    $('#storyGrid').innerHTML = '<div class="empty-state">Stories could not be loaded. Check that the blog feed is enabled.</div>';
  });
}

function renderDetailInfo(story) {
  $('#detailPoster').src = story.poster || POCKETFM_CONFIG.PLACEHOLDER_POSTER;
  $('#detailPoster').alt = `${story.title} poster`;
  $('#detailTitle').textContent = story.title;
  $('#detailDescription').textContent = story.description || 'Story information will be updated soon.';
  $('#detailBadges').innerHTML = [story.genre, story.subGenre, story.language, story.status].filter(Boolean).map(value => `<span class="badge">${escapeHtml(value)}</span>`).join('');
  const info = [
    ['Genre', story.genre], ['Sub Genre', story.subGenre], ['Language', story.language], ['Voice Artist', story.voiceArtist],
    ['Status', story.status], ['Episodes', story.episodes], ['Author', story.author], ['Release Year', story.releaseYear],
    ['Listening Hours', story.listeningHours], ['Rating', story.rating]
  ].filter(([, value]) => value);
  $('#detailInfo').innerHTML = info.map(([label, value]) => `<div class="info-item"><span class="info-label">${escapeHtml(label)}</span><span class="info-value">${escapeHtml(value)}</span></div>`).join('');
  const pocketButton = $('#pocketButton');
  if (!POCKETFM_CONFIG.SHOW_POCKETFM_BUTTON || !story.pocketUrl || story.pocketUrl === '#') {
    pocketButton.style.display = 'none';
  } else {
    pocketButton.href = story.pocketUrl;
  }
  renderStructuredData(story);
}

function renderStructuredData(story) {
  const graph = {
    '@context': 'https://schema.org',
    '@graph': [
      { '@type': 'BreadcrumbList', itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'Home', item: getBlogBaseUrl() },
        { '@type': 'ListItem', position: 2, name: story.title, item: location.href }
      ]},
      { '@type': 'CreativeWork', name: story.title, description: story.description, image: story.poster, genre: [story.genre, story.subGenre].filter(Boolean), inLanguage: story.language, author: story.author ? { '@type': 'Person', name: story.author } : undefined, url: location.href, sameAs: story.pocketUrl || undefined }
    ]
  };
  const script = document.createElement('script');
  script.type = 'application/ld+json';
  script.textContent = JSON.stringify(graph);
  document.head.appendChild(script);
}

async function renderRelatedStories(currentStory) {
  const row = $('#relatedStories');
  if (!row || !currentStory.voiceArtist) {
    if (row) row.innerHTML = '<div class="empty-state">No related voice artist stories yet.</div>';
    return;
  }
  try {
    while (!appState.loadedAll && appState.stories.length < POCKETFM_CONFIG.FEED_BATCH_SIZE * 3) await fetchStoriesBatch();
    const related = appState.stories.filter(story => story.voiceArtist === currentStory.voiceArtist && story.url !== currentStory.url).slice(0, 18);
    row.innerHTML = related.length ? related.map(cardTemplate).join('') : '<div class="empty-state">No related voice artist stories yet.</div>';
  } catch (error) {
    console.error(error);
    row.innerHTML = '<div class="empty-state">Related stories could not be loaded.</div>';
  }
}

async function initDetailPage() {
  if (!$('#storyDetail')) return;
  try {
    const story = await getCurrentPostMetadata();
    renderDetailInfo(story);
    renderRelatedStories(story);
  } catch (error) {
    console.error(error);
    $('#detailDescription').textContent = 'Story metadata could not be loaded. Make sure the post contains STORY_DATA_START and STORY_DATA_END metadata and that the Blogger site feed includes full post content.';
    $('#pocketButton').style.display = 'none';
    $('#relatedStories').innerHTML = '<div class="empty-state">Related stories could not be loaded.</div>';
  }
}

function initStaticPage() {
  const target = $('#staticPageContent');
  if (!target) return;
  const source = $('.blog-posts .post .post-body');
  target.innerHTML = source ? source.innerHTML : '<p>Add content to this Blogger page from the Pages editor.</p>';
}

function initNavigation() {
  const nav = $('#siteNav');
  const toggle = $('#navToggle');
  toggle?.addEventListener('click', () => {
    const open = nav.classList.toggle('is-open');
    toggle.setAttribute('aria-expanded', String(open));
  });
}

document.addEventListener('DOMContentLoaded', () => {
  $('#yearNow').textContent = new Date().getFullYear();
  initNavigation();
  initStaticPage();
  initIndexPage();
  initDetailPage();
});
